#!/usr/bin/env bash
# Copy the monorepo source dirs the image build reads into $HIBISCUS_ROOT, at the
# flat names the tools/ scripts expect (tools, overlay, hsvr, vrhome, ...).
#
# The GitHub workflow's "layout sources" step and a local run both go through
# this, so the two build from an identical set: a dir added here lands in
# every image, a dir missing here lands in none.
#
#   HIBISCUS_ROOT=/path/to/build-root system/dist/scripts/layout-sources.sh
#   system/dist/scripts/layout-sources.sh --list   (just the dst names)
set -euo pipefail

# src-in-repo:dst-under-HIBISCUS_ROOT. Input packages (pvr_stack, blobs, ...) are
# not sources - fetch-inputs.sh lays those out. system/fullstage is read
# repo-relative by make-loadingres-img.sh, so it is not here either; the
# $HIBISCUS_ROOT/fullstage staging tree is generated by 144_stage_full.sh.
PAIRS=(
  "system/tools:tools"
  "system/overlay:overlay"
  "system/shim:shim"
  "system/hsvr:hsvr"
  "system/cted:cted"
  "drivers:drivers"
  # globbed by monado/build.sh for kit controllers - empty today, but a driver
  # landing here must reach every build, not only local ones
  "controllers:controllers"
  "applications/vrhome:vrhome"
  # shared by the panel apps through a ../panel_theme path dep - has to
  # sit next to them in the flat layout for the reference to resolve
  "applications/panel_theme:panel_theme"
  "applications/store:store"
  "applications/keyboard:keyboard"
)

if [ "${1:-}" = "--list" ]; then
  printf '%s\n' "${PAIRS[@]##*:}"
  exit 0
fi

R="${HIBISCUS_ROOT:?set HIBISCUS_ROOT to a build root - see system/dist/README.md}"
REPO="$(cd "$(dirname "$0")/../../.." && pwd -P)"

# $HIBISCUS_ROOT is a scratch root, never the checkout - the copies below replace
# dst dirs wholesale, and dst names (drivers/, tools/) collide with real
# repo dirs.
[ -d "$R" ] || mkdir -p "$R"
if [ "$(cd "$R" && pwd -P)" = "$REPO" ]; then
  echo "HIBISCUS_ROOT is the repo checkout - point it at a build root" >&2
  exit 1
fi

for pair in "${PAIRS[@]}"; do
  src="${pair%%:*}"; dst="${pair##*:}"
  [ -d "$REPO/$src" ] || { echo "missing source dir $src" >&2; exit 1; }
  # replace, not merge: files dropped by an older copy (renamed sources,
  # stale build output) would otherwise linger and reach the image - the
  # GitHub runner always starts clean, so local should too
  rm -rf "$R/$dst"
  cp -a "$REPO/$src" "$R/$dst"
done

# the dirs fetch-inputs.sh and the pipeline expect to exist
mkdir -p "$R"/{notes,out,fullstage,gsi,images,.stub/media}
ls -la "$R"
